import unittest
from datetime import datetime
from src.ai_coding_trend_analyzer import commit_parser

class TestCommitParser(unittest.TestCase):
    def setUp(self):
        self.log_text = (
            "---COMMIT---\n"
            "abc123\n"
            "Alice\n"
            "2024-05-01 10:00:00 +0000\n"
            "Initial commit\n"
            "---END---\n"
            "---COMMIT---\n"
            "def456\n"
            "Bob\n"
            "2024-05-02 12:30:00 +0000\n"
            "Added feature (generated by AI)\n"
            "---END---\n"
            "---COMMIT---\n"
            "ghi789\n"
            "Carol\n"
            "2024-05-03 15:45:00 +0000\n"
            "Refactor: improved performance\nAI suggestion: optimize loop\n"
            "---END---\n"
        )
        self.commits = commit_parser.parse_git_log(self.log_text)

    def test_parse_git_log(self):
        self.assertEqual(len(self.commits), 3)
        self.assertEqual(self.commits[0].hash, "abc123")
        self.assertEqual(self.commits[1].author, "Bob")
        self.assertIn("AI", self.commits[1].message)

    def test_has_agent_indicator(self):
        self.assertFalse(self.commits[0].has_agent_indicator())
        self.assertTrue(self.commits[1].has_agent_indicator())
        self.assertTrue(self.commits[2].has_agent_indicator())

    def test_find_agent_related_commits(self):
        result = commit_parser.find_agent_related_commits(self.commits)
        self.assertEqual(len(result), 3)
        self.assertFalse(result[0]['agent_keyword_found'])
        self.assertTrue(result[1]['agent_keyword_found'])
        self.assertTrue(result[2]['agent_keyword_found'])
        self.assertEqual(result[1]['hash'], "def456")
        self.assertEqual(result[2]['author'], "Carol")

    def test_extract_timestamps_and_agent_usage(self):
        from src.ai_coding_trend_analyzer.commit_parser import extract_timestamps_and_agent_usage
        data = extract_timestamps_and_agent_usage(self.commits)
        self.assertEqual(len(data), 3)
        # Check structure
        for entry in data:
            self.assertIn('timestamp', entry)
            self.assertIn('agent_keyword_found', entry)
            self.assertIsInstance(entry['timestamp'], datetime)
            self.assertIsInstance(entry['agent_keyword_found'], bool)
        # Check values
        self.assertFalse(data[0]['agent_keyword_found'])
        self.assertTrue(data[1]['agent_keyword_found'])
        self.assertTrue(data[2]['agent_keyword_found'])
        self.assertEqual(data[0]['timestamp'].year, 2024)
        self.assertEqual(data[1]['timestamp'].month, 5)

    def test_extract_timestamps_and_agent_usage_handles_bad_date(self):
        # Commit with malformed date
        bad_commit = commit_parser.Commit("zzz999", "Eve", "not-a-date", "copilot suggestion")
        from src.ai_coding_trend_analyzer.commit_parser import extract_timestamps_and_agent_usage
        data = extract_timestamps_and_agent_usage([bad_commit])
        self.assertIsNone(data[0]['timestamp'])
        self.assertTrue(data[0]['agent_keyword_found'])

if __name__ == "__main__":
    unittest.main()
